use crate::aap::caps::http_client;
use crate::aap::caps::state_rw;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's HTTPClient handle is scoped to. A request outside
/// this set traps at the boundary, so such URLs are reported as failures
/// instead of being requested.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// The key under which every call records the input it received.
const LAST_INPUT_KEY: &str = "last-input";

struct Node;

/// Returns the lowercased host of an http(s) URL, or None if it cannot be parsed.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };
    let authority_end = rest
        .find(|c| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..authority_end];
    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    // Drop any port.
    let host = match host_port.rfind(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };
    let host = host.trim_end_matches('.');
    if host.is_empty() {
        None
    } else {
        Some(host.to_ascii_lowercase())
    }
}

fn is_allowed(url: &str) -> bool {
    match host_of(url) {
        Some(h) => ALLOWED_HOSTS.iter().any(|a| *a == h),
        None => false,
    }
}

fn json_escape(s: &str, out: &mut String) {
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
}

/// Encodes the subscription list as JSON: {"urls":["...", ...]}.
fn encode_input(subscriptions: &SubscriptionList) -> String {
    let mut out = String::from("{\"urls\":[");
    for (i, url) in subscriptions.urls.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        json_escape(url, &mut out);
    }
    out.push_str("]}");
    out
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        // Record the input received on this call in the shared store.
        state_rw::put(LAST_INPUT_KEY, &encode_input(&subscriptions));

        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls.iter() {
            if !is_allowed(url) {
                failures.push(FetchFailure {
                    url: url.clone(),
                    error: String::from("host not in allowlist; not requested"),
                });
                continue;
            }
            match http_client::fetch(url) {
                Ok(body) => documents.push(FeedDocument {
                    url: url.clone(),
                    body,
                }),
                Err(error) => failures.push(FetchFailure {
                    url: url.clone(),
                    error,
                }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
